let rec factorial n =
    if n <= 1 then 1 else n * factorial (n - 1)

printfn "%d" (factorial 10)

signature.code:
// A computation expression builder: let! short-circuits when a step is None.
type MaybeBuilder() =
    member _.Bind(x, f) = Option.bind f x
    member _.Return x = Some x

let maybe = MaybeBuilder()

let parse (s: string) =
    match System.Int32.TryParse s with
    | true, n -> Some n
    | _ -> None

let addStrings a b = maybe {
    let! x = parse a
    let! y = parse b
    return x + y }

// The same notation powers async workflows (2007), the ancestor of async/await.
let total = async {
    let! parts = Async.Parallel [ async { return 20 }; async { return 22 } ]
    return Array.sum parts }

printfn "%A" (addStrings "20" "22")
printfn "%A" (addStrings "20" "x")
printfn "%d" (Async.RunSynchronously total)
